output_text:
[
  {
    "id": "return_cart_to_bay",
    "text": "A shopper must return the cart to the designated return bay at the top-left area before the trip ends.",
    "abstraction": {
      "state_properties": {
        "at_cart_return_bay": "at(0,1)",
        "cart_parked_in_return_bay": "cartAt(0,1)"
      },
      "events": {
        "return_cart_to_bay": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "hasCart",
              "at_cart_return_bay"
            ]
          },
          "post": "cart_parked_in_return_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "return_cart_to_bay"
    }
  },
  {
    "id": "no_abandon_cart_outside_bay",
    "text": "It is forbidden to leave a cart anywhere except the designated return bay.",
    "abstraction": {
      "state_properties": {
        "at_cart_return_bay": "at(0,1)"
      },
      "events": {
        "leave_cart_outside_bay": {
          "pre": {
            "and": [
              "LEAVE_CART",
              {
                "not": "at_cart_return_bay"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_cart_outside_bay"
    }
  },
  {
    "id": "picked_cart_must_be_returned",
    "text": "Once a shopper takes a cart, they are obliged to park it in the return bay before finishing.",
    "abstraction": {
      "state_properties": {
        "at_cart_return_bay": "at(0,1)",
        "cart_parked_in_return_bay": "cartAt(0,1)"
      },
      "events": {
        "take_cart": {
          "pre": "PICKUP_CART",
          "post": "hasCart"
        },
        "return_cart_to_bay": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "at_cart_return_bay"
            ]
          },
          "post": "cart_parked_in_return_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "take_cart",
      "discharge": "return_cart_to_bay"
    }
  },
  {
    "id": "exit_only_after_cart_parked",
    "text": "A shopper may exit only after the cart is parked in the designated return bay.",
    "abstraction": {
      "state_properties": {
        "cart_parked_in_return_bay": "cartAt(0,1)"
      },
      "events": {
        "exit_store": {
          "pre": "EXIT",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "exit_store",
          {
            "not": "cart_parked_in_return_bay"
          }
        ]
      }
    }
  },
  {
    "id": "parked_cart_only_in_allowed_places",
    "text": "Whenever the cart is not being held, it may be parked only at the initial cart stack or the return bay.",
    "abstraction": {
      "state_properties": {
        "cart_in_start_stack": "cartAt(1,5)",
        "cart_in_return_bay": "cartAt(0,1)",
        "cart_is_parked": {
          "not": "hasCart"
        },
        "cart_in_allowed_parking_place": {
          "or": [
            "cart_in_start_stack",
            "cart_in_return_bay"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "cart_is_parked",
          {
            "not": "cart_in_allowed_parking_place"
          }
        ]
      }
    }
  },
  {
    "id": "use_cart_for_item_pickup",
    "text": "Items must be picked up only while the shopper has a cart, not carried directly by hand.",
    "abstraction": {
      "state_properties": {
        "carrying_cart": "hasCart",
        "carrying_item_by_hand": "handFull"
      },
      "events": {
        "pickup_item_without_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              {
                "not": "carrying_cart"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "pickup_item_without_cart",
          "carrying_item_by_hand"
        ]
      }
    }
  },
  {
    "id": "shopping_with_cart_creates_return_duty",
    "text": "After putting any item into a cart, the shopper becomes obliged to return that cart to the return bay.",
    "abstraction": {
      "state_properties": {
        "at_cart_return_bay": "at(0,1)",
        "cart_parked_in_return_bay": "cartAt(0,1)"
      },
      "events": {
        "item_put_in_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "hasCart"
            ]
          },
          "post": "hasCart"
        },
        "return_cart_to_bay": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "at_cart_return_bay"
            ]
          },
          "post": "cart_parked_in_return_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "item_put_in_cart",
      "discharge": "return_cart_to_bay"
    }
  },
  {
    "id": "do_not_exit_with_cart",
    "text": "It is forbidden to leave the store while still holding or pushing a cart.",
    "abstraction": {
      "state_properties": {
        "has_cart": "hasCart"
      },
      "events": {
        "exit_with_cart": {
          "pre": {
            "and": [
              "EXIT",
              "has_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "exit_with_cart"
    }
  }
]
